using VisualRelay.GitSim;
using GitSimEngine = VisualRelay.GitSim.GitSim;

namespace VisualRelay.Tests;

public class MergeDebugTest
{
    const string FieldSep = "\u001f";
    const string RecordSep = "\u001e";
    const string ClaimEmail = "claimed@example.test";
    const string ClaimName = "Claimed Author";

    public static async Task Run()
    {
        var dir = Path.Combine(Path.GetTempPath(), "merge-debug-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(dir);
        try
        {
            var sim = new GitSimEngine();
            sim.InitRepo(dir);
            sim.Seed(dir, "a.txt", "1");
            sim.Commit(dir, "feat: base\\n");
            Console.WriteLine("Base commit sha: " + sim.Head(dir));

            await sim.Git(dir, "checkout", "-b", "side");
            sim.Seed(dir, "side.txt", "side");
            await sim.Git(dir, "commit", "-m", "feat: side");
            var sideSha = sim.Head(dir);
            Console.WriteLine("Side commit sha: " + sideSha);
            Console.WriteLine("Head on side: " + sim.Head(dir));

            await sim.Git(dir, "checkout", "main");
            sim.Seed(dir, "main2.txt", "main2");
            await sim.Git(dir, "commit", "-m", "feat: main2");
            var main2Sha = sim.Head(dir);
            Console.WriteLine("Main2 commit sha: " + main2Sha);
            Console.WriteLine("Head on main: " + sim.Head(dir));

            var mergeResult = await sim.Git(dir, "merge", "--no-ff", "--no-edit", "side");
            Console.WriteLine("Merge exit: " + mergeResult.ExitCode);
            Console.WriteLine("Merge output: " + mergeResult.Output.Trim());
            var mergeSha = sim.Head(dir);
            Console.WriteLine("Merge commit sha: " + mergeSha);

            // Check commit info
            var info = sim.CommitInfo(dir, mergeSha);
            Console.WriteLine("Merge commit parents count: " + (info?.Parents.Count ?? 0));
            if (info != null)
                foreach (var p in info.Parents)
                    Console.WriteLine("  Parent: " + p);

            // Now check what log --format with %P produces
            var format = "%H" + FieldSep + "%T" + FieldSep + "%P" + FieldSep + "%an" + FieldSep + "%ae" + FieldSep + "%aI" + FieldSep + "%ce" + FieldSep + "%B" + RecordSep;
            var logResult = await sim.Git(dir, "log", "--reverse", "--format=" + format, "HEAD");
            Console.WriteLine("Log exit: " + logResult.ExitCode);
            Console.WriteLine("Log output:");
            Console.WriteLine(logResult.Output);

            // Parse like the claimer does
            var hasMerge = false;
            foreach (var record in logResult.Output.Split(RecordSep))
            {
                var trimmed = record.TrimStart('\\n');
                if (trimmed.Length == 0) continue;
                var f = trimmed.Split(FieldSep);
                if (f.Length < 8) continue;
                var parents = f[2].Length == 0
                    ? Array.Empty<string>()
                    : f[2].Split(' ', StringSplitOptions.RemoveEmptyEntries);
                Console.WriteLine("Commit " + f[0][..Math.Min(7, f[0].Length)] + " parents: " + parents.Length);
                if (parents.Length > 1) hasMerge = true;
            }
            Console.WriteLine("Has merge: " + hasMerge);
        }
        finally
        {
            try { Directory.Delete(dir, true); } catch { }
        }
    }
}
