/// <summary>Verify that a `--no-ff` merge commit truly carries two parents in GitSim.</summary>
private static async Task ValidateMergeCommitPresenceAsync(GitSimEngine sim, string root)
{
    // Check total commit count.
    var (exit0, output0, _) = await sim.RunAsync(root, ["log", "--format=%H", "HEAD"], CancellationToken.None);
    Assert.Equal(0, exit0);
    var commitCount = output0.Split('\n', StringSplitOptions.RemoveEmptyEntries).Length;
    Assert.True(commitCount >= 4, $"expected >=4 commits, got {commitCount}");

    // The most recent commit (top of HEAD log) must have two parents.
    var (exit, output, _) = await sim.RunAsync(root, ["log", "--format=%P", "HEAD"], CancellationToken.None, timeout: TimeSpan.FromSeconds(5));
    Assert.Equal(0, exit);
    var firstLine = output.Split('\n', StringSplitOptions.RemoveEmptyEntries).FirstOrDefault();
    Assert.NotNull(firstLine);
    var parentCount = firstLine.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length;
    Assert.Equal(2, parentCount);
}
